<?php
/**
 * QPOS browser-print installer. Delete this file immediately after use.
 */
error_reporting(E_ALL);
ini_set('display_errors', '0');
header('Content-Type: text/html; charset=UTF-8');

$requiredKey = 'qposclear2026';
$providedKey = isset($_GET['key']) && is_string($_GET['key']) ? $_GET['key'] : '';
if (!hash_equals($requiredKey, $providedKey)) {
    http_response_code(403);
    echo '<!doctype html><meta charset="utf-8"><title>QPOS Installer</title><h1>Forbidden</h1><p>Use the authorized installer URL.</p>';
    exit;
}

$results = array();
$add = function ($status, $message) use (&$results) {
    $results[] = array($status, $message);
};
$h = function ($value) {
    return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
};
$describe = function ($path) {
    clearstatcache(true, $path);
    if (!is_file($path)) {
        return $path . ' (missing)';
    }
    $size = filesize($path);
    $sha1 = sha1_file($path);
    $mtime = filemtime($path);
    return $path . ' | ' . $size . ' bytes | SHA1 ' . $sha1 . ' | modified ' . ($mtime ? date('c', $mtime) : 'unknown');
};

// Locate Laravel whether this installer is in the project root or its public directory.
$root = null;
$probe = realpath(__DIR__);
for ($level = 0; $level < 8 && $probe !== false; $level++) {
    if (is_file($probe . '/bootstrap/app.php') && is_file($probe . '/vendor/autoload.php') && is_dir($probe . '/app') && is_dir($probe . '/routes')) {
        $root = $probe;
        break;
    }
    $parent = dirname($probe);
    if ($parent === $probe) {
        break;
    }
    $probe = $parent;
}

if ($root === null) {
    http_response_code(500);
    $add('bad', 'Laravel root not found. Place this installer in the URL document root or Laravel public directory.');
} else {
    $add('ok', 'Laravel root detected: ' . $root);
}

$payloads = array(
    'app/Http/Controllers/LabelsController.php' => array('data' => '', 'sha1' => 'd93bd9ebb7cf649777133535ae64ccd3c675d323'),
    'resources/views/labels/browser_print.blade.php' => array('data' => '', 'sha1' => '260169411f281ea7c953a811bc0682a6a2dbacce'),
    'public/js/labels.js' => array('data' => '', 'sha1' => 'cffd9d85f333052ff7b3e4cdc82a76bae12dd806'),
    'lang/en/lang_v1.php' => array('data' => '', 'sha1' => '21416f96d508b0db4bfaea02ca56e0b781410ee1'),
);

$backupSuffix = '.qpos-backup-' . date('Ymd-His') . '-' . substr(sha1(uniqid('', true)), 0, 8);
$writeTarget = function ($relative, $encoded, $expectedSha1) use ($root, $backupSuffix, $add, $describe) {
    if ($root === null) {
        return false;
    }
    $target = $root . '/' . $relative;
    $decoded = base64_decode($encoded, true);
    if ($decoded === false || sha1($decoded) !== $expectedSha1) {
        $add('bad', 'Embedded payload validation failed: ' . $relative);
        return false;
    }
    $directory = dirname($target);
    if (!is_dir($directory) && !@mkdir($directory, 0755, true) && !is_dir($directory)) {
        $add('bad', 'Cannot create directory: ' . $directory);
        return false;
    }
    $oldMode = is_file($target) ? (fileperms($target) & 0777) : 0644;
    if (is_file($target)) {
        $backup = $target . $backupSuffix;
        if (!@copy($target, $backup)) {
            $add('bad', 'Backup failed; target was not changed: ' . $target);
            return false;
        }
        $add('ok', 'Backup created: ' . $backup);
    }
    $bytes = @file_put_contents($target, $decoded, LOCK_EX);
    if ($bytes === false || $bytes !== strlen($decoded)) {
        $add('bad', 'Write failed or incomplete: ' . $target);
        return false;
    }
    @chmod($target, $oldMode ?: 0644);
    if (substr($target, -4) === '.php') {
        clearstatcache(true, $target);
    }
    if (sha1_file($target) !== $expectedSha1) {
        $add('bad', 'Post-write SHA1 mismatch: ' . $target);
        return false;
    }
    $add('ok', 'Installed: ' . $describe($target));
    return true;
};

$controllerPath = $root !== null ? $root . '/app/Http/Controllers/LabelsController.php' : '';
foreach ($payloads as $relative => $payload) {
    $written = $writeTarget($relative, $payload['data'], $payload['sha1']);
    if ($written && $relative === 'app/Http/Controllers/LabelsController.php') {
        clearstatcache(true, $controllerPath);
        if (function_exists('opcache_invalidate')) {
            try {
                $invalidated = opcache_invalidate($controllerPath, true);
                $add($invalidated ? 'ok' : 'warn', 'OPcache controller invalidation: ' . ($invalidated ? 'successful' : 'not available for this file'));
            } catch (Throwable $throwable) {
                $add('warn', 'OPcache controller invalidation error: ' . $throwable->getMessage());
            }
        } else {
            $add('warn', 'OPcache controller invalidation function is unavailable.');
        }
    }
}

// Ensure the route exists without replacing unrelated route customizations.
if ($root !== null) {
    $routePath = $root . '/routes/web.php';
    if (!is_file($routePath)) {
        $add('bad', 'Routes file missing: ' . $routePath);
    } else {
        $routes = @file_get_contents($routePath);
        if ($routes === false) {
            $add('bad', 'Cannot read routes file: ' . $routePath);
        } elseif (strpos($routes, '/labels/browser-print') !== false && strpos($routes, 'browserPrint') !== false) {
            clearstatcache(true, $routePath);
            $add('ok', 'Browser-print route already present: ' . $describe($routePath));
        } else {
            $anchor = "Route::get('/labels/export-bartender-csv'";
            $routeLine = "    Route::get('/labels/browser-print', [\\App\\Http\\Controllers\\LabelsController::class, 'browserPrint']);";
            $anchorPosition = strpos($routes, $anchor);
            if ($anchorPosition !== false) {
                $lineEnd = strpos($routes, "\n", $anchorPosition);
                if ($lineEnd === false) {
                    $lineEnd = strlen($routes);
                }
                $updatedRoutes = substr($routes, 0, $lineEnd + 1) . $routeLine . "\n" . substr($routes, $lineEnd + 1);
            } else {
                $updatedRoutes = rtrim($routes) . "\n\nRoute::middleware(['setData', 'auth', 'SetSessionData', 'language', 'timezone'])->get('/labels/browser-print', [\\App\\Http\\Controllers\\LabelsController::class, 'browserPrint']);\n";
            }
            $routeBackup = $routePath . $backupSuffix;
            if (!@copy($routePath, $routeBackup)) {
                $add('bad', 'Route backup failed; routes were not changed: ' . $routePath);
            } elseif (@file_put_contents($routePath, $updatedRoutes, LOCK_EX) === false) {
                $add('bad', 'Could not write browser-print route: ' . $routePath);
            } else {
                clearstatcache(true, $routePath);
                $add('ok', 'Route backup created: ' . $routeBackup);
                $add('ok', 'Browser-print route added: ' . $describe($routePath));
            }
        }
    }
}

// Remove compiled Blade output directly, independently of framework startup.
if ($root !== null) {
    $viewDirectory = $root . '/storage/framework/views';
    $removed = 0;
    $failed = 0;
    if (is_dir($viewDirectory)) {
        try {
            $iterator = new RecursiveIteratorIterator(
                new RecursiveDirectoryIterator($viewDirectory, FilesystemIterator::SKIP_DOTS),
                RecursiveIteratorIterator::CHILD_FIRST
            );
            foreach ($iterator as $entry) {
                if ($entry->isFile() && $entry->getFilename() !== '.gitignore') {
                    if (@unlink($entry->getPathname())) {
                        $removed++;
                    } else {
                        $failed++;
                    }
                }
            }
            $add($failed === 0 ? 'ok' : 'warn', 'Compiled Blade files removed: ' . $removed . '; failures: ' . $failed);
        } catch (Throwable $throwable) {
            $add('warn', 'Direct compiled-view cleanup error: ' . $throwable->getMessage());
        }
    } else {
        $add('warn', 'Compiled-view directory not found: ' . $viewDirectory);
    }
}

// Bootstrap Laravel and clear each cache independently. Every framework action is guarded.
if ($root !== null) {
    try {
        require_once $root . '/vendor/autoload.php';
        $app = require $root . '/bootstrap/app.php';
        $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class);
        $kernel->bootstrap();
        $add('ok', 'Laravel console kernel bootstrapped.');
        foreach (array('route:clear', 'view:clear', 'cache:clear') as $artisanCommand) {
            try {
                Illuminate\Support\Facades\Artisan::call($artisanCommand);
                $output = trim(Illuminate\Support\Facades\Artisan::output());
                $add('ok', 'Artisan ' . $artisanCommand . ' completed' . ($output !== '' ? ': ' . $output : '.'));
            } catch (Throwable $throwable) {
                $add('warn', 'Artisan ' . $artisanCommand . ' failed safely: ' . $throwable->getMessage());
            }
        }
    } catch (Throwable $throwable) {
        $add('warn', 'Laravel bootstrap failed safely: ' . $throwable->getMessage());
    }
}

$controllerHasMethod = false;
if ($controllerPath !== '') {
    clearstatcache(true, $controllerPath);
    $controllerSource = @file_get_contents($controllerPath);
    $controllerHasMethod = is_string($controllerSource) && strpos($controllerSource, 'function browserPrint') !== false;
    $add($controllerHasMethod ? 'ok' : 'bad', 'Controller source method check: ' . ($controllerHasMethod ? 'function browserPrint found' : 'function browserPrint NOT FOUND'));
    $add($controllerHasMethod ? 'ok' : 'bad', 'Controller verification: ' . $describe($controllerPath));
}

if (function_exists('opcache_reset')) {
    try {
        $reset = opcache_reset();
        $add($reset ? 'ok' : 'warn', 'Final OPcache reset: ' . ($reset ? 'successful' : 'returned false'));
    } catch (Throwable $throwable) {
        $add('warn', 'Final OPcache reset error: ' . $throwable->getMessage());
    }
} else {
    $add('warn', 'Final OPcache reset function is unavailable.');
}

$hasBad = false;
foreach ($results as $result) {
    if ($result[0] === 'bad') {
        $hasBad = true;
        break;
    }
}
?>
<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>QPOS Browser Print Installer</title>
<style>body{font:16px/1.45 system-ui,sans-serif;background:#f4f7fb;color:#172033;margin:0;padding:30px}.card{max-width:1050px;margin:auto;background:#fff;padding:28px;border-radius:14px;box-shadow:0 8px 28px #1d355722}h1{margin-top:0}.result{padding:10px 12px;margin:8px 0;border-radius:8px;overflow-wrap:anywhere}.ok{background:#e8f7ee;color:#146c3c}.warn{background:#fff4d6;color:#805b00}.bad{background:#fde8e8;color:#a21c1c}.notice{margin-top:24px;padding:18px;border:3px solid #c62828;background:#fff0f0;color:#8e1616;font-weight:700;font-size:18px}.done{padding:14px;background:#e8f7ee;color:#146c3c;border-radius:8px;font-weight:700}</style></head><body><main class="card">
<h1>QPOS Browser Print Installer</h1>
<p class="<?php echo $hasBad ? 'bad result' : 'done'; ?>"><?php echo $hasBad ? 'Completed with errors. Review every line below.' : 'Installation completed. Review warnings, delete this installer, then test browser print.'; ?></p>
<?php foreach ($results as $result): ?><div class="result <?php echo $h($result[0]); ?>"><strong><?php echo strtoupper($h($result[0])); ?>:</strong> <?php echo $h($result[1]); ?></div><?php endforeach; ?>
<div class="notice">If the live application still says LabelsController::browserPrint does not exist, restart PHP-FPM from cPanel MultiPHP Manager. If no restart control is available, change the domain PHP version and then change it back.</div>
<p><strong>Security:</strong> Delete this installer from the server now.</p>
</main></body></html>
